using System;
using UnityEngine;

namespace PocketWilds.Presentation
{
    /// <summary>
    /// Scatter placements of one chunk (SCT_&lt;Chunk&gt;), generated by the editor scatter tool, never placed by hand.
    /// Instances are grouped by kind; inside a group they are ordered by a stable hash rank, so a quality tier
    /// keeps a prefix of each group: Fluide always shows the same 30%, spread evenly.
    /// </summary>
    [CreateAssetMenu(menuName = "Pocket Wilds/World/Scatter Data", fileName = "SCT_Chunk")]
    public sealed class ScatterData : ScriptableObject
    {
        [Serializable]
        public struct Group
        {
            [Tooltip("Index in the kit's kinds.")] public int kind;
            public int start;
            public int count;
        }

        public ScatterKit kit;
        public Group[] groups = Array.Empty<Group>();
        [Tooltip("xyz: position in chunk space (m), w: yaw (radians).")]
        public Vector4[] placements = Array.Empty<Vector4>();
        [Tooltip("Uniform scale per placement.")]
        public float[] scales = Array.Empty<float>();
        [Tooltip("Bounds of every placement in chunk space, plant height included.")]
        public Bounds bounds;

        public int Count => placements.Length;

        public Matrix4x4 LocalMatrix(int index)
        {
            var p = placements[index];
            return Matrix4x4.TRS(new Vector3(p.x, p.y, p.z), Quaternion.Euler(0f, p.w * Mathf.Rad2Deg, 0f), Vector3.one * scales[index]);
        }
    }
}
